function TRANS_RANK(f, i, j, n):
    acc <- I_n                       # identity endomorphism
    if j <= i: return rank(acc)      # empty/reversed window
    for t from i to j-1:
        acc <- f(t) @ acc            # trans(f,i,t+1) = f(t) . trans(f,i,t)
    return rank(acc)                 # dim of image
